import { delete_scheduled_game } from "@/graphql/mutations";
import { API, graphqlOperation } from "aws-amplify";
import SnackBar from "../SnackBar.vue";
export default {
  props: {
    DialogDeleteScheduledGame: Boolean,
    StoreObj: Object
  },
  components: {
    SnackBar
  },
  data: () => ({
    loading: false,
    SnackBarComponent: {}
  }),
  methods: {
    async DeleteScheduledGame() {
      this.loading = true;
      try {
        const result = await API.graphql(graphqlOperation(delete_scheduled_game, {
          input: {
            game_session_id: this.StoreObj.game_session_id
          }
        }));
        let resultObj = JSON.parse(result.data.delete_scheduled_game);
        if (resultObj.Status === "SUCCESS") {
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "green",
            SnackbarText: resultObj.Message
          };
        }
        this.loading = false;
        this.DialogDeleteScheduledGameEmit(2);
      } catch (error) {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: "Failed to delete scheduled game, try again"
        };
      } finally {
        this.loading = false;
      }
    },
    DialogDeleteScheduledGameEmit(Toggle) {
      this.$emit("clicked", Toggle);
    },
    Convert(value) {
      if (!value) return "N/A";
      const date = new Date(value * 1000);
      let hours = date.getHours();
      const minutes = String(date.getMinutes()).padStart(2, "0");
      const ampm = hours >= 12 ? "PM" : "AM";
      hours = hours % 12 || 12;
      return `${String(date.getDate()).padStart(2, "0")}-${String(date.getMonth() + 1).padStart(2, "0")}-${date.getFullYear()}, ${hours}:${minutes}:${ampm}`;
    }
  }
};
